cd /workspace && python3 - <<'EOF'
from parse import parse as p
for fmt in ['{:', '{:}', '{', '}', '{:z}', '{{', '{:w!']:
    try:
        r = p(fmt, 'x')
        print(repr(fmt), '-> no exception, result:', r)
    except Exception as e:
        print(repr(fmt), '->', type(e).__name__, ':', e)
EOF
